async fn read_exact_timeout(
    reader: &mut ReadHalf<CurrentConnection>,
    buf: &mut [u8],
    timeout: Duration,
) -> Result<()> {
    match tokio::time::timeout(timeout, reader.read_exact(buf)).await {
        Ok(res) => {
            res?;
            Ok(())
        }
        Err(_elapsed) => Err(RustADBError::ReadTimeout),
    }
}

